// ============================================================
// 🔵 PRE-VISIT AGENT — RULES ENGINE: Mandatory Field Validation
// ============================================================
// Validates all required fields, insurance format, conditional
// logic (pregnancy for females 15-55), and computes risk score.
// This node handles ALL deterministic pre-visit validation.
// ============================================================

const items = $input.all();
const results = [];

for (const item of items) {
  let data = item.json;
  // --- UNWRAP WEBHOOK DATA ---
  // Webhook wraps POST body in {headers, body, params, ...}; form triggers send flat data
  if (data.body && data.webhookUrl) { data = data.body; }

  const now = new Date().toISOString();

  // --- NORMALIZE INPUT (handle both Form and Webhook) ---
  let fullName = data.personalInfo?.fullName || data['Full Name'] || data.fullName || '';
  let dateOfBirth = data.personalInfo?.dateOfBirth || data['Date of Birth'] || data.dateOfBirth || '';
  let gender = data.personalInfo?.gender || data['Gender'] || data.gender || '';
  let phone = data.personalInfo?.phone || data['Phone'] || data.phone || '';
  let email = data.personalInfo?.email || data['Email'] || data.email || '';
  let insurancePolicyNumber = data.insurancePolicyNumber || data['Insurance Policy Number'] || '';

  // Medical history
  let conditionsRaw = data.medicalHistory?.currentConditions || data['Current Conditions (comma-separated)'] || data.currentConditions || '';
  let medicationsRaw = data.medicalHistory?.currentMedications || data['Current Medications (comma-separated)'] || data.currentMedications || '';
  let allergiesRaw = data.medicalHistory?.allergies || data['Allergies (comma-separated)'] || data.allergies || '';
  let smokingStatus = data.smokingStatus || data['Smoking Status'] || 'never';
  let pregnancyStatus = data.pregnancyStatus || data['Pregnancy Status (females 15-55 only)'] || null;

  // Parse comma-separated strings into arrays if needed
  let conditions = Array.isArray(conditionsRaw) 
    ? conditionsRaw 
    : (typeof conditionsRaw === 'string' && conditionsRaw.trim() 
       ? conditionsRaw.split(',').map(s => s.trim().toLowerCase()) 
       : []);

  let medications = Array.isArray(medicationsRaw)
    ? medicationsRaw
    : (typeof medicationsRaw === 'string' && medicationsRaw.trim()
       ? medicationsRaw.split(',').map(s => ({ name: s.trim(), dosage: '', frequency: '' }))
       : []);

  let allergies = Array.isArray(allergiesRaw)
    ? allergiesRaw
    : (typeof allergiesRaw === 'string' && allergiesRaw.trim()
       ? allergiesRaw.split(',').map(s => s.trim())
       : []);

  // Normalize gender
  gender = (typeof gender === 'string') ? gender.toLowerCase().trim() : '';
  smokingStatus = (typeof smokingStatus === 'string') ? smokingStatus.toLowerCase().trim() : 'never';

  // --- MANDATORY FIELD ENFORCEMENT ---
  const missingFields = [];
  const validationErrors = [];

  if (!fullName || fullName.trim().length === 0) {
    missingFields.push('fullName');
    validationErrors.push({ field: 'fullName', error: 'Full name is required.', code: 'MISSING_REQUIRED' });
  }
  if (!dateOfBirth || dateOfBirth.trim().length === 0) {
    missingFields.push('dateOfBirth');
    validationErrors.push({ field: 'dateOfBirth', error: 'Date of birth is required.', code: 'MISSING_REQUIRED' });
  }
  if (!gender || !['male', 'female', 'other'].includes(gender)) {
    missingFields.push('gender');
    validationErrors.push({ field: 'gender', error: 'Gender is required. Must be male, female, or other.', code: 'MISSING_REQUIRED' });
  }
  if (!phone || phone.trim().length === 0) {
    missingFields.push('phone');
    validationErrors.push({ field: 'phone', error: 'Phone number is required.', code: 'MISSING_REQUIRED' });
  }
  if (!insurancePolicyNumber || insurancePolicyNumber.trim().length === 0) {
    missingFields.push('insurancePolicyNumber');
    validationErrors.push({ field: 'insurancePolicyNumber', error: 'Insurance policy number is required.', code: 'MISSING_REQUIRED' });
  }
  if (conditions.length === 0) {
    missingFields.push('currentConditions');
    validationErrors.push({ field: 'currentConditions', error: 'Current conditions are required. Enter "none" if none.', code: 'MISSING_REQUIRED' });
  }

  // --- INSURANCE FORMAT VALIDATION ---
  const insurancePattern = /^POL-[A-Z]{2}-[0-9]{8}$/;
  let insuranceValid = true;
  if (insurancePolicyNumber && !insurancePattern.test(insurancePolicyNumber.trim())) {
    insuranceValid = false;
    validationErrors.push({
      field: 'insurancePolicyNumber',
      error: `Invalid insurance policy format. Expected: POL-XX-XXXXXXXX (e.g., POL-MY-20230415). Received: "${insurancePolicyNumber}"`,
      code: 'INVALID_FORMAT'
    });
  }

  // --- CONDITIONAL LOGIC: Pregnancy Question ---
  let pregnancyRequired = false;
  let age = 0;
  if (dateOfBirth && dateOfBirth.trim()) {
    try {
      const dob = new Date(dateOfBirth);
      const today = new Date();
      age = Math.floor((today - dob) / (365.25 * 24 * 60 * 60 * 1000));
    } catch(e) { age = 0; }
  }

  if (gender === 'female' && age >= 15 && age <= 55) {
    pregnancyRequired = true;
    if (!pregnancyStatus || pregnancyStatus === 'N/A' || pregnancyStatus.trim().length === 0) {
      missingFields.push('pregnancyStatus');
      validationErrors.push({
        field: 'pregnancyStatus',
        error: 'Pregnancy status is required for female patients aged 15-55.',
        code: 'CONDITIONAL_REQUIRED'
      });
    }
  }

  // --- RISK SCORE CALCULATION ---
  const riskPoints = {
    'hypertension': 3,
    'chest-pain': 4,
    'diabetes': 2,
    'heart-disease': 4,
    'stroke-history': 4,
    'cancer': 3,
    'kidney-disease': 2,
    'liver-disease': 2
  };

  let riskScore = 0;
  const riskFactors = [];

  for (const condition of conditions) {
    const c = condition.toLowerCase().replace(/\s+/g, '-');
    if (riskPoints[c]) {
      riskScore += riskPoints[c];
      riskFactors.push(`${c} (+${riskPoints[c]})`);
    }
  }

  if (smokingStatus === 'current') {
    riskScore += 2;
    riskFactors.push('current-smoker (+2)');
  }
  if (age > 65) {
    riskScore += 2;
    riskFactors.push('age>65 (+2)');
  }

  let riskLevel = 'low';
  if (riskScore >= 11) riskLevel = 'critical';
  else if (riskScore >= 7) riskLevel = 'high';
  else if (riskScore >= 4) riskLevel = 'medium';

  const escalationTriggered = riskScore >= 7;

  // --- DETERMINE COMPLETION STATUS ---
  let completionStatus = 'complete';
  if (missingFields.length > 0) {
    completionStatus = 'incomplete';
  }

  // --- BUILD FOLLOW-UP TASK FOR INCOMPLETE SUBMISSIONS ---
  let followUpTask = null;
  if (completionStatus === 'incomplete') {
    const patientId = data.patientId || 'PAT-' + String(Math.floor(Math.random() * 99999999)).padStart(8, '0');
    const timestamp = Date.now();
    followUpTask = {
      taskId: `FU-${patientId}-${timestamp}`,
      scheduledAt: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(),
      channel: 'sms',
      retryPolicy: { maxRetries: 2, retryIntervalHours: 24 },
      reminderMessage: `Dear ${fullName || 'Patient'}, your intake form is incomplete. Please complete the following fields: ${missingFields.join(', ')}. Complete within 24 hours to avoid appointment delays.`
    };
  }

  // --- ESCALATION DEDUPLICATION ---
  let escalationDeduplicated = false;
  let dedupKey = '';
  if (escalationTriggered) {
    const patientId = data.patientId || 'PAT-UNKNOWN';
    const dateStr = new Date().toISOString().split('T')[0];
    dedupKey = `pre-visit|${patientId}|${dateStr}`;

    const staticData = $getWorkflowStaticData('global');
    if (!staticData.escalationKeys) staticData.escalationKeys = {};

    if (staticData.escalationKeys[dedupKey]) {
      escalationDeduplicated = true;
    } else {
      staticData.escalationKeys[dedupKey] = now;
    }
  }

  // --- BUILD RESPONSE ---
  const intakeId = 'INT-' + String(Math.floor(Math.random() * 99999999)).padStart(8, '0');

  const response = {
    status: completionStatus === 'complete' && !validationErrors.some(e => e.code === 'INVALID_FORMAT') ? 'accepted' : 'validation_failed',
    intakeId: intakeId,
    completionStatus: completionStatus,
    personalInfo: {
      fullName: fullName,
      dateOfBirth: dateOfBirth,
      gender: gender,
      phone: phone,
      email: email,
      age: age
    },
    insurancePolicyNumber: insurancePolicyNumber,
    insuranceValid: insuranceValid,
    medicalHistory: {
      currentConditions: conditions,
      currentMedications: medications,
      allergies: allergies.filter(a => a.toLowerCase() !== 'none')
    },
    pregnancyStatus: pregnancyRequired ? (pregnancyStatus || 'NOT_PROVIDED') : 'N/A',
    pregnancyRequired: pregnancyRequired,
    smokingStatus: smokingStatus,
    riskScore: {
      score: riskScore,
      level: riskLevel,
      escalationTriggered: escalationTriggered,
      riskFactors: riskFactors,
      computedAt: now
    },
    missingFields: missingFields,
    validationErrors: validationErrors,
    followUpTask: followUpTask,
    escalation: escalationTriggered ? {
      triggered: true,
      deduplicated: escalationDeduplicated,
      type: 'nurse-queue',
      assignedTo: 'nurse-queue',
      priority: riskLevel,
      slaDeadline: new Date(Date.now() + 60 * 60 * 1000).toISOString(),
      reason: `High risk score ${riskScore} (${riskLevel}). Factors: ${riskFactors.join(', ')}`
    } : {
      triggered: false,
      deduplicated: false
    },
    auditLog: [
      {
        event: 'INTAKE_RECEIVED',
        timestamp: now,
        agent: 'pre-visit',
        intakeId: intakeId,
        patientName: fullName
      },
      {
        event: completionStatus === 'complete' && insuranceValid ? 'INTAKE_VALIDATED' : 'INTAKE_VALIDATION_FAILED',
        timestamp: now,
        agent: 'pre-visit',
        intakeId: intakeId,
        missingFields: missingFields,
        validationErrors: validationErrors.map(e => e.code)
      },
      ...(followUpTask ? [{
        event: 'FOLLOW_UP_TASK_CREATED',
        timestamp: now,
        agent: 'pre-visit',
        taskId: followUpTask.taskId,
        scheduledAt: followUpTask.scheduledAt
      }] : []),
      ...(escalationTriggered && !escalationDeduplicated ? [{
        event: 'ESCALATION_CREATED',
        timestamp: now,
        agent: 'pre-visit',
        intakeId: intakeId,
        riskScore: riskScore,
        riskLevel: riskLevel,
        assignedTo: 'nurse-queue'
      }] : []),
      ...(escalationDeduplicated ? [{
        event: 'ESCALATION_DEDUP_BLOCKED',
        timestamp: now,
        agent: 'pre-visit',
        dedupKey: dedupKey
      }] : [])
    ]
  };

  results.push({ json: response });
}

return results;

// ============================================================
// 🔵 PRE-VISIT — ESCALATION ENGINE: Create Nurse Queue Ticket
// ============================================================

const data = $input.first().json;
const now = new Date().toISOString();

if (data.escalation.deduplicated) {
  return [{
    json: {
      httpStatus: 409,
      status: 'duplicate_escalation_blocked',
      message: 'An escalation for this patient has already been created today. Duplicate blocked.',
      intakeId: data.intakeId,
      riskScore: data.riskScore,
      auditLog: data.auditLog
    }
  }];
}

const ticketId = 'ESC-' + String(Math.floor(Math.random() * 99999999)).padStart(8, '0');
const alertId = 'ALT-' + String(Math.floor(Math.random() * 99999999)).padStart(8, '0');

return [{
  json: {
    status: 'escalated',
    message: `HIGH RISK INTAKE: Patient ${data.personalInfo.fullName} has risk score ${data.riskScore.score} (${data.riskScore.level}). Escalated to nurse queue for immediate review.`,
    intakeId: data.intakeId,
    personalInfo: data.personalInfo,
    riskScore: data.riskScore,
    escalation: {
      ticketId: ticketId,
      alertId: alertId,
      type: 'nurse-queue',
      assignedTo: 'nurse-queue',
      priority: data.riskScore.level,
      slaDeadline: data.escalation.slaDeadline,
      reason: data.escalation.reason
    },
    auditLog: [
      ...data.auditLog,
      {
        event: 'ESCALATION_TICKET_CREATED',
        timestamp: now,
        agent: 'pre-visit',
        ticketId: ticketId,
        alertId: alertId,
        assignedTo: 'nurse-queue',
        priority: data.riskScore.level
      }
    ]
  }
}];

// ============================================================
// 🔵 PRE-VISIT — Normal Confirmation Response
// ============================================================

const data = $input.first().json;

return [{
  json: {
    status: data.status,
    message: data.status === 'accepted' 
      ? `Intake form accepted for ${data.personalInfo.fullName}. Risk level: ${data.riskScore.level}. ${data.pregnancyRequired && data.pregnancyStatus === 'NOT_PROVIDED' ? 'ACTION REQUIRED: Please provide pregnancy status.' : 'All fields validated successfully.'}` 
      : `Intake form has validation issues. ${data.missingFields.length > 0 ? 'Missing fields: ' + data.missingFields.join(', ') + '.' : ''} ${data.validationErrors.filter(e => e.code === 'INVALID_FORMAT').map(e => e.error).join(' ')} ${data.pregnancyRequired && data.pregnancyStatus === 'NOT_PROVIDED' ? 'Pregnancy status required for female patients aged 15-55.' : ''}`,
    intakeId: data.intakeId,
    completionStatus: data.completionStatus,
    personalInfo: data.personalInfo,
    insuranceValid: data.insuranceValid,
    riskScore: data.riskScore,
    missingFields: data.missingFields,
    validationErrors: data.validationErrors,
    pregnancyRequired: data.pregnancyRequired,
    pregnancyStatus: data.pregnancyStatus,
    followUpTask: data.followUpTask,
    auditLog: data.auditLog
  }
}];

// ============================================================
// 🟢 POST-VISIT AGENT — Input Validation & Normalization
// ============================================================

const items = $input.all();
const results = [];

for (const item of items) {
  let data = item.json;
  // --- UNWRAP WEBHOOK DATA ---
  // Webhook wraps POST body in {headers, body, params, ...}; form triggers send flat data
  if (data.body && data.webhookUrl) { data = data.body; }

  const now = new Date().toISOString();

  // Normalize input
  let patientId = data.patientId || data['Patient ID'] || '';
  let visitId = data.visitId || data['Visit ID'] || '';
  let painScore = data.painScore ?? data['Pain Score (0-10)'] ?? null;
  let freeTextResponse = data.freeTextResponse || data['How are you feeling? Describe any symptoms'] || '';
  let temperature = data.temperature || data.temperatureReported || data['Temperature (°C, if measured)'] || null;

  // Parse numeric values
  if (painScore !== null && painScore !== undefined) {
    painScore = parseInt(painScore, 10);
    if (isNaN(painScore)) painScore = null;
  }
  if (temperature !== null && temperature !== undefined && temperature !== '') {
    temperature = parseFloat(temperature);
    if (isNaN(temperature)) temperature = null;
  } else {
    temperature = null;
  }

  // Validate
  const errors = [];
  if (!patientId) errors.push('patientId is required');
  if (!visitId) errors.push('visitId is required');
  if (painScore === null || painScore === undefined) errors.push('painScore is required (0-10)');
  if (painScore !== null && (painScore < 0 || painScore > 10)) errors.push('painScore must be between 0 and 10');
  if (!freeTextResponse || freeTextResponse.trim().length === 0) errors.push('symptom description is required');

  results.push({
    json: {
      patientId,
      visitId,
      painScore,
      freeTextResponse: freeTextResponse.trim(),
      temperatureReported: temperature,
      validationErrors: errors,
      isValid: errors.length === 0,
      checkId: 'PVC-' + String(Math.floor(Math.random() * 99999999)).padStart(8, '0'),
      checkInTime: now
    }
  });
}

return results;

