// ============================================================
// 🟢 POST-VISIT — Process NLP Results & Escalation Decision
// ============================================================

const nlpResponse = $input.first().json;
const prevData = $('🟢 Post-Visit: Validate Input').first().json;
const now = new Date().toISOString();

// Parse NLP result
let nlpResult;
try {
  const content = nlpResponse.choices?.[0]?.message?.content || '{}';
  nlpResult = JSON.parse(content);
} catch(e) {
  // LLM failure fallback — escalate to manual review
  nlpResult = {
    redFlagsDetected: false,
    flags: [],
    extractedSymptoms: [],
    overallAssessment: 'normal',
    reasoning: 'LLM parse error — manual review recommended'
  };
}

const painScore = prevData.painScore;
const temperature = prevData.temperatureReported;
const patientId = prevData.patientId;
const visitId = prevData.visitId;
const freeText = prevData.freeTextResponse;
const checkId = prevData.checkId;

// --- ADDITIONAL RULES ENGINE CHECKS ---

// High fever check (rules engine, not LLM)
if (temperature !== null && temperature > 38.5) {
  if (!nlpResult.flags) nlpResult.flags = [];
  const alreadyHasFever = nlpResult.flags.some(f => f.category === 'high-fever');
  if (!alreadyHasFever) {
    nlpResult.redFlagsDetected = true;
    nlpResult.flags.push({
      category: 'high-fever',
      matchedPhrase: `temperature ${temperature}°C`,
      confidence: 1.0,
      severity: 'severe'
    });
  }
}

// High pain score check (rules engine)
const highPain = painScore >= 7;

// Pain-text conflict detection
const minimizingPhrases = ['fine', 'okay', 'not bad', 'alright', 'no problem', 'manageable', 'it\'s nothing', 'don\'t worry'];
const textLower = freeText.toLowerCase();
const isMinimizing = minimizingPhrases.some(phrase => textLower.includes(phrase));
const conflictDetected = highPain && isMinimizing;

// Determine escalation
let escalationType = 'none';
let assignedTo = null;
let slaMins = 0;
let escalationReason = '';

const hasBreathingFlag = nlpResult.flags?.some(f => f.category === 'shortness-of-breath');
const hasBleedingFlag = nlpResult.flags?.some(f => f.category === 'bleeding' && f.severity === 'severe');

if (hasBreathingFlag || hasBleedingFlag) {
  escalationType = 'emergency';
  assignedTo = 'emergency-services';
  slaMins = 5;
  escalationReason = `Emergency red flag: ${hasBreathingFlag ? 'shortness of breath' : 'severe bleeding'} detected`;
} else if (nlpResult.redFlagsDetected || highPain || conflictDetected) {
  escalationType = 'clinical';
  slaMins = 60;

  const hasMedSideEffect = nlpResult.flags?.some(f => f.category === 'medication-side-effect');
  if (hasMedSideEffect) {
    assignedTo = 'prescribing-doctor';
    escalationReason = 'Medication side effect detected — escalated to prescribing doctor';
  } else if (temperature && temperature > 38.5) {
    assignedTo = 'physician';
    escalationReason = `Fever ${temperature}°C above threshold — escalated to physician`;
  } else if (conflictDetected) {
    assignedTo = 'clinical-team';
    escalationReason = `Pain score conflict: patient scores ${painScore}/10 but uses minimizing language. Escalated despite patient dismissal.`;
  } else {
    assignedTo = 'clinical-team';
    escalationReason = `Red flags detected: ${nlpResult.flags?.map(f => f.category).join(', ')}`;
  }
}

// --- ESCALATION DEDUPLICATION ---
let escalationDeduplicated = false;
let dedupKey = '';
if (escalationType !== 'none') {
  const dateStr = new Date().toISOString().split('T')[0];
  dedupKey = `post-visit|${patientId}|${dateStr}`;
  const staticData = $getWorkflowStaticData('global');
  if (!staticData.escalationKeys) staticData.escalationKeys = {};
  if (staticData.escalationKeys[dedupKey]) {
    escalationDeduplicated = true;
  } else {
    staticData.escalationKeys[dedupKey] = now;
  }
}

// --- BUILD PROACTIVE CHECK-IN (for non-escalated) ---
let proactiveCheckIn = null;
if (escalationType === 'none') {
  proactiveCheckIn = {
    taskId: `CI-${visitId}-${Date.now()}`,
    scheduledAt: new Date(Date.now() + 48 * 60 * 60 * 1000).toISOString(),
    channel: 'sms',
    escalationIfNoResponse: {
      waitHours: 48,
      action: 'escalate-to-nurse'
    }
  };
}

// --- MULTI-TURN CONVERSATION STATE MANAGEMENT ---
const conversationStaticData = $getWorkflowStaticData('global');
if (!conversationStaticData.conversations) conversationStaticData.conversations = {};

const conversationKey = `conv|${patientId}|${visitId}`;
let existingConversation = conversationStaticData.conversations[conversationKey];
let turnNumber = 1;

if (existingConversation) {
  turnNumber = existingConversation.turnNumber + 1;
  if (turnNumber > 5) turnNumber = 5; // Max 5 turns
}

// Store state after escalation is determined
conversationStaticData.conversations[conversationKey] = {
  turnNumber: turnNumber,
  lastCheckinAt: now,
  lastPainScore: painScore,
  escalated: escalationType !== 'none'
};

// --- CONVERSATION LOG ---
const conversationLog = {
  sessionId: `SESSION-${visitId}-${Date.now()}`,
  turnNumber: turnNumber,
  maxTurns: 5,
  previousTurns: turnNumber > 1 ? turnNumber - 1 : 0,
  isFollowUp: turnNumber > 1,
  entries: [
    {
      role: 'patient',
      content: freeText,
      timestamp: now,
      intent: 'symptom-report',
      painScore: painScore
    }
  ]
};

// --- AUDIT LOG ---
const auditLog = [
  {
    event: 'POST_VISIT_CHECK_IN_RECEIVED',
    timestamp: now,
    agent: 'post-visit',
    checkId: checkId,
    patientId: patientId,
    visitId: visitId,
    painScore: painScore
  }
];

if (nlpResult.redFlagsDetected) {
  auditLog.push({
    event: 'RED_FLAG_DETECTED',
    timestamp: now,
    agent: 'post-visit',
    checkId: checkId,
    flags: nlpResult.flags?.map(f => f.category),
    confidence: nlpResult.flags?.map(f => f.confidence)
  });
}

if (conflictDetected) {
  auditLog.push({
    event: 'PAIN_SCORE_CONFLICT_DETECTED',
    timestamp: now,
    agent: 'post-visit',
    painScore: painScore,
    minimizingText: true
  });
}

if (escalationType !== 'none' && !escalationDeduplicated) {
  auditLog.push({
    event: 'ESCALATION_CREATED',
    timestamp: now,
    agent: 'post-visit',
    type: escalationType,
    assignedTo: assignedTo,
    reason: escalationReason
  });
}

if (escalationDeduplicated) {
  auditLog.push({
    event: 'ESCALATION_DEDUP_BLOCKED',
    timestamp: now,
    agent: 'post-visit',
    dedupKey: dedupKey
  });
}

if (proactiveCheckIn) {
  auditLog.push({
    event: 'PROACTIVE_CHECKIN_SCHEDULED',
    timestamp: now,
    agent: 'post-visit',
    taskId: proactiveCheckIn.taskId,
    scheduledAt: proactiveCheckIn.scheduledAt
  });
}

const result = {
  checkId: checkId,
  patientId: patientId,
  visitId: visitId,
  painScore: painScore,
  temperatureReported: temperature,
  freeTextResponse: freeText,
  nlpClassification: {
    redFlagsDetected: nlpResult.redFlagsDetected || false,
    flags: nlpResult.flags || [],
    extractedSymptoms: nlpResult.extractedSymptoms || [],
