const llmResponse = $input.first().json;
const prevData = $('🔴 Triage: Emergency Scanner').first().json;
const now = new Date().toISOString();

const DISCLAIMER = '\n\n⚠️ IMPORTANT DISCLAIMER: This system does not provide medical diagnoses. The information above is for guidance only and should not replace professional medical advice. If your symptoms worsen or you feel your condition is an emergency, please call 999 or visit the nearest emergency department immediately.';

// Parse LLM result
let llmResult;
try {
  const content = llmResponse.choices?.[0]?.message?.content || '{}';
  llmResult = JSON.parse(content);
} catch(e) {
  llmResult = {
    classification: 'Insufficient',
    confidence: 0,
    reasoning: 'Unable to parse LLM response — defaulting to Insufficient for safety',
    guidance: 'We could not fully assess your symptoms. Please provide more details or contact our clinic directly.',
    followUpQuestions: ['Can you describe your symptoms in more detail?', 'When did the symptoms start?', 'Have you taken any medication?'],
    suggestedAction: 'Please contact our clinic directly for assistance.',
    redFlags: []
  };
}

const classification = llmResult.classification || 'Insufficient';
const auditLog = [];

// Build response based on classification
let escalation = { triggered: false };
let message = '';

if (classification === 'Emergency') {
  const ticketId = 'ESC-' + String(Math.floor(Math.random() * 99999999)).padStart(8, '0');
  escalation = {
    triggered: true,
    type: 'emergency-services',
    assignedTo: 'emergency-services',
