    ticketId: ticketId
  };
  message = `🚨 URGENT: Based on your symptoms, this may require emergency medical attention. Please call 999 or go to your nearest emergency department immediately. ${llmResult.guidance || ''}${DISCLAIMER}`;

  auditLog.push({
    event: 'TRIAGE_EMERGENCY',
    timestamp: now,
    agent: 'clinical-triage',
    patientId: prevData.patientId,
    classification: 'Emergency',
    llmBased: true
  });
} else if (classification === 'Same-Day') {
  message = `⚡ Your symptoms suggest you should see a doctor today. ${llmResult.guidance || 'Please book a same-day appointment at our clinic.'} ${llmResult.suggestedAction || ''}${DISCLAIMER}`;

  auditLog.push({
    event: 'TRIAGE_CLASSIFIED',
    timestamp: now,
    agent: 'clinical-triage',
    patientId: prevData.patientId,
    classification: 'Same-Day',
