  });
} else if (classification === 'Routine') {
  message = `📋 Your symptoms appear to be routine. ${llmResult.guidance || 'We recommend booking an appointment at your next available convenience.'} ${llmResult.suggestedAction || ''}${DISCLAIMER}`;

  auditLog.push({
    event: 'TRIAGE_CLASSIFIED',
    timestamp: now,
    agent: 'clinical-triage',
    patientId: prevData.patientId,
    classification: 'Routine',
    confidence: llmResult.confidence
  });
} else {
  // Insufficient
