  auditLog.push({
    event: 'TRIAGE_FOLLOWUP_QUESTIONS',
    timestamp: now,
    agent: 'clinical-triage',
    patientId: prevData.patientId,
    classification: 'Insufficient',
    questionsAsked: llmResult.followUpQuestions?.length || 0
  });
}

return [{
  json: {
    status: classification === 'Emergency' ? 'EMERGENCY' : classification.toUpperCase(),
    classification: classification,
    message: message,
