      reasoning: llmResult.reasoning,
      guidance: llmResult.guidance,
      followUpQuestions: llmResult.followUpQuestions || [],
      suggestedAction: llmResult.suggestedAction,
      redFlags: llmResult.redFlags || []
    },
    escalation: escalation,
