// ============================================================
// 🟠 BILLING AGENT — Step 1: Validate & Normalize Input
// ============================================================
// Handles: Webhook/form data unwrap, field normalization,
// treatment code parsing, supporting documents, FAQ detection.
// ============================================================

const items = $input.all();
const results = [];

for (const item of items) {
  let data = item.json;
  // --- UNWRAP WEBHOOK DATA ---
  if (data.body && data.webhookUrl) { data = data.body; }

  const now = new Date().toISOString();
  const auditLog = [];

  // --- NORMALIZE INPUT ---
  let patientId = data.patientId || data['Patient ID'] || '';
  let visitId = data.visitId || data['Visit ID'] || '';
  let treatmentCodesRaw = data.treatmentCodes || data['Treatment Codes (comma-separated)'] || '';
  let amount = data.amount || data['Invoice Amount (MYR)'] || 0;
  let invoiceDate = data.invoiceDate || data['Invoice Date'] || new Date().toISOString().split('T')[0];
  let insurancePolicyId = data.insurancePolicyId || data['Insurance Policy ID'] || '';
  let policyExpiryDate = data.policyExpiryDate || data['Policy Expiry Date'] || '';
  let coveredCodesRaw = data.coveredCodes || data['Covered Codes (comma-separated)'] || '';
  let billingQuestion = data.billingQuestion || data['Billing Question (optional)'] || '';
  let overrideCode = data.overrideCode || data['Manual Override Code (optional)'] || '';
  let overrideJustification = data.overrideJustification || data['Override Justification (required if override)'] || '';

  // Parse arrays
  let treatmentCodes = Array.isArray(treatmentCodesRaw)
    ? treatmentCodesRaw
    : (typeof treatmentCodesRaw === 'string' && treatmentCodesRaw.trim()
       ? treatmentCodesRaw.split(',').map(s => s.trim().toUpperCase())
       : []);

  let coveredCodes = Array.isArray(coveredCodesRaw)
    ? coveredCodesRaw
    : (typeof coveredCodesRaw === 'string' && coveredCodesRaw.trim()
       ? coveredCodesRaw.split(',').map(s => s.trim().toUpperCase())
       : []);

  if (typeof amount === 'string') amount = parseFloat(amount) || 0;

  // --- SUPPORTING DOCUMENTS ---
  let submittedDocs = data.supportingDocuments || data['Supporting Documents (comma-separated)'] || [];
  if (typeof submittedDocs === 'string') {
    submittedDocs = submittedDocs.split(',').map(s => s.trim().toLowerCase().replace(/\s+/g, '_'));
  }

  // --- FAQ ENGINE ---
  let faqResponse = null;
  if (billingQuestion && billingQuestion.trim().length > 0) {
    const faqDatabase = [
      { category: 'billing_status', keywords: ['status', 'where is my bill', 'claim status', 'invoice status', 'pending'], answer: 'Your billing claim is being processed. Most claims are resolved within 14 business days. If your claim is older than 30 days, it will be automatically escalated to a billing manager.', escalateIfUnresolved: true },
      { category: 'copay', keywords: ['copay', 'co-pay', 'my share', 'out of pocket', 'how much do I pay'], answer: 'Your copay amount depends on your insurance plan and the treatment received. Please check your insurance policy details or contact your insurer directly for specific copay information.', escalateIfUnresolved: false },
      { category: 'deductible', keywords: ['deductible', 'annual limit', 'coverage limit', 'maximum'], answer: 'Your deductible and coverage limits are defined in your insurance policy. Once the annual deductible is met, your insurance covers eligible treatments up to the annual maximum.', escalateIfUnresolved: false },
      { category: 'denied_claim', keywords: ['denied', 'rejected', 'claim denied', 'not approved', 'rejection'], answer: 'If your claim was denied, please review the rejection reason provided. Common causes include: expired policy, treatment not covered, or missing documentation. You may submit an appeal with supporting documents.', escalateIfUnresolved: true },
      { category: 'payment_options', keywords: ['payment', 'pay', 'installment', 'payment plan', 'how to pay'], answer: 'We accept cash, credit/debit card, bank transfer, and insurance claims. For large bills, installment payment plans may be available \u2014 please speak with our billing team.', escalateIfUnresolved: false },
      { category: 'refund', keywords: ['refund', 'overpaid', 'overcharged', 'money back', 'credit'], answer: 'Refund requests are processed within 14 business days after verification. Please provide your invoice number and the reason for the refund request. Our billing team will review and respond.', escalateIfUnresolved: true },
      { category: 'insurance_contact', keywords: ['insurance phone', 'insurance email', 'contact insurer', 'insurance company'], answer: 'Please contact your insurance provider directly using the contact information on your insurance card. Our billing team can also assist in liaising with your insurer if needed.', escalateIfUnresolved: false },
      { category: 'general_billing', keywords: ['bill', 'charge', 'cost', 'fee', 'price', 'receipt', 'statement'], answer: 'For general billing inquiries, please provide your Patient ID and Visit ID. Our billing system tracks all charges by visit. Itemized statements are available upon request.', escalateIfUnresolved: false }
    ];

    const questionLower = billingQuestion.toLowerCase();
    let bestMatch = null;
    let bestScore = 0;

    for (const faq of faqDatabase) {
      const matchCount = faq.keywords.filter(kw => questionLower.includes(kw)).length;
      if (matchCount > bestScore) {
        bestScore = matchCount;
        bestMatch = faq;
      }
    }

    if (bestMatch) {
      faqResponse = {
        category: bestMatch.category,
        answer: bestMatch.answer,
        matched: true,
        escalateIfUnresolved: bestMatch.escalateIfUnresolved
      };
    } else {
      faqResponse = {
        category: 'unmatched',
        answer: 'Your billing question has been noted. A billing specialist will review and respond within 24 hours.',
        matched: false,
        escalateIfUnresolved: true
      };
    }

    auditLog.push({
      event: 'BILLING_FAQ_RESPONSE',
      timestamp: now,
      agent: 'billing',
      category: faqResponse.category,
      matched: faqResponse.matched,
      question: billingQuestion.substring(0, 200)
    });
  }

  auditLog.push({
    event: 'BILLING_RECEIVED',
    timestamp: now,
    agent: 'billing',
    patientId: patientId,
    visitId: visitId
  });

  results.push({
    json: {
      patientId, visitId, treatmentCodes, amount, invoiceDate,
      insurancePolicyId, policyExpiryDate, coveredCodes,
      billingQuestion, overrideCode, overrideJustification,
      submittedDocs, faqResponse, auditLog, _timestamp: now
    }
  });
}

return results;

// ============================================================
// 🟠 BILLING AGENT — Step 2: Eligibility & Duplicate Check
// ============================================================
// Handles: Idempotency (duplicate invoice detection),
// insurance expiry validation, documentation requirements,
// SLA tracking (>30 days auto-escalation).
// ============================================================

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const now = data._timestamp;
  const auditLog = [...(data.auditLog || [])];

  // --- MISSING DOCUMENTATION DETECTION ---
  const documentationRequirements = {
    'CONS': ['consultation_notes'],
    'LAB':  ['lab_request', 'lab_results'],
    'XRAY': ['imaging_request', 'imaging_report'],
    'SURG': ['surgical_consent', 'pre_op_assessment', 'discharge_summary'],
    'PHYS': ['therapy_plan'],
    'PRESC': ['prescription'],
    'PROC': ['procedure_notes', 'consent_form']
  };

  let missingDocuments = [];
  let documentationComplete = true;

  for (const code of data.treatmentCodes) {
    const prefix = code.replace(/[0-9]/g, '');
    const requiredDocs = documentationRequirements[prefix] || [];
    for (const doc of requiredDocs) {
      if (!data.submittedDocs.includes(doc)) {
        missingDocuments.push({ treatmentCode: code, requiredDocument: doc, description: doc.replace(/_/g, ' ') });
        documentationComplete = false;
      }
    }
  }

  if (!documentationComplete) {
    auditLog.push({
      event: 'MISSING_DOCUMENTATION_DETECTED',
      timestamp: now,
      agent: 'billing',
      missingDocuments: missingDocuments,
      treatmentCodes: data.treatmentCodes,
      message: 'Required supporting documents are missing for one or more treatment codes.'
    });
  }

  // --- INSURANCE EXPIRY VALIDATION ---
  let insuranceExpired = false;
  let insuranceErrors = [];

  if (data.policyExpiryDate) {
    const expiryDate = new Date(data.policyExpiryDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (expiryDate < today) {
      insuranceExpired = true;
      insuranceErrors.push(`Insurance policy ${data.insurancePolicyId} expired on ${data.policyExpiryDate}. Claim cannot be processed against expired policy.`);
      auditLog.push({
        event: 'INSURANCE_EXPIRED_DETECTED',
        timestamp: now,
        agent: 'billing',
        policyId: data.insurancePolicyId,
        expiryDate: data.policyExpiryDate
      });
    }
  }

  // --- SLA TRACKING ---
  const invoiceDateObj = new Date(data.invoiceDate);
  const daysOutstanding = Math.floor((new Date() - invoiceDateObj) / (1000 * 60 * 60 * 24));
  const slaBreached = daysOutstanding > 30;

  let billingEscalation = null;
  if (slaBreached) {
    billingEscalation = {
      triggered: true,
      type: 'billing-manager',
      assignedTo: 'billing-manager',
      reason: `Claim outstanding for ${daysOutstanding} days (SLA threshold: 30 days). Auto-escalated to billing manager.`,
      slaDeadline: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
    };
    auditLog.push({
      event: 'SLA_BREACH_DETECTED',
      timestamp: now,
      agent: 'billing',
      daysOutstanding: daysOutstanding,
      assignedTo: 'billing-manager'
    });
  }

  // --- IDEMPOTENCY / DUPLICATE DETECTION ---
  const sortedCodes = [...data.treatmentCodes].sort().join('|');
  const idempotencyKey = `${data.patientId}|${data.visitId}|${sortedCodes}|${data.invoiceDate}`;

  const staticData = $getWorkflowStaticData('global');
  if (!staticData.invoiceKeys) staticData.invoiceKeys = {};

  let isDuplicate = false;
  let existingInvoiceId = null;

  if (staticData.invoiceKeys[idempotencyKey]) {
    isDuplicate = true;
    existingInvoiceId = staticData.invoiceKeys[idempotencyKey];
    auditLog.push({
      event: 'DUPLICATE_INVOICE_BLOCKED',
      timestamp: now,
      agent: 'billing',
      idempotencyKey: idempotencyKey,
      existingInvoiceId: existingInvoiceId
    });
  }

  results.push({
    json: {
      ...data,
      isDuplicate, existingInvoiceId, idempotencyKey,
      insuranceExpired, insuranceErrors,
      documentationComplete, missingDocuments,
      daysOutstanding, slaBreached, billingEscalation,
      auditLog
    }
  });
}

return results;

// ============================================================
// 🟠 BILLING AGENT — Duplicate Invoice Blocked
// ============================================================
// Returns structured response when a duplicate invoice is
// detected via idempotency key matching.
// ============================================================

const data = $input.first().json;

return [{
  json: {
    status: data.insuranceExpired ? 'rejected' : (data.slaBreached ? 'overdue' : 'duplicate_blocked'),
    message: data.insuranceExpired
      ? `Claim rejected: ${data.insuranceErrors.join(' ')} (Duplicate of ${data.existingInvoiceId})`
      : (data.slaBreached
        ? `Claim overdue: ${data.daysOutstanding} days outstanding. SLA breach. (Duplicate of ${data.existingInvoiceId})`
        : `Duplicate invoice detected. Invoice already exists (${data.existingInvoiceId}). Blocked.`),
    idempotencyKey: data.idempotencyKey,
    existingInvoiceId: data.existingInvoiceId,
    insuranceExpired: data.insuranceExpired,
    slaTracking: { invoiceDate: data.invoiceDate, daysOutstanding: data.daysOutstanding, slaBreached: data.slaBreached },
    faqResponse: data.faqResponse,
    auditLog: data.auditLog
  }
}];

// ============================================================
// 🟠 BILLING AGENT — Process & Submit Claim
// ============================================================
// Handles: Invoice creation, treatment code vs coverage
// matching, manual override with audit trail, claim status
// determination (submitted/rejected/held/overdue).
// ============================================================

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const now = data._timestamp;
  const auditLog = [...(data.auditLog || [])];

  // Register this invoice
  const invoiceId = 'INV-' + String(Math.floor(Math.random() * 99999999)).padStart(8, '0');
  const staticData = $getWorkflowStaticData('global');
  if (!staticData.invoiceKeys) staticData.invoiceKeys = {};
  staticData.invoiceKeys[data.idempotencyKey] = invoiceId;

  auditLog.push({
    event: 'INVOICE_CREATED',
    timestamp: now,
    agent: 'billing',
    invoiceId: invoiceId,
    patientId: data.patientId,
    amount: data.amount
  });

  // --- TREATMENT CODE vs COVERAGE MATCH ---
  let mismatchDetected = false;
  let mismatchedCodes = [];

  if (data.coveredCodes.length > 0) {
    for (const code of data.treatmentCodes) {
      if (!data.coveredCodes.includes(code)) {
        mismatchDetected = true;
        mismatchedCodes.push(code);
      }
    }

    if (mismatchDetected) {
      auditLog.push({
        event: 'TREATMENT_CODE_MISMATCH',
        timestamp: now,
        agent: 'billing',
        mismatchedCodes: mismatchedCodes,
        coveredCodes: data.coveredCodes
      });
    }
  }

  // --- MANUAL OVERRIDE ---
  let overrideResult = null;
  const validOverrideCodes = ['MGR-APPROVE', 'EXEC-WAIVER', 'COMPASSION-OVERRIDE', 'POLICY-EXCEPTION'];

  if (data.overrideCode && data.overrideCode.trim().length > 0) {
    if (!validOverrideCodes.includes(data.overrideCode.trim().toUpperCase())) {
      overrideResult = {
        applied: false,
        error: `Invalid override code: "${data.overrideCode}". Valid codes: ${validOverrideCodes.join(', ')}`
      };
    } else if (!data.overrideJustification || data.overrideJustification.trim().length < 10) {
      overrideResult = {
        applied: false,
        error: 'Override justification is required and must be at least 10 characters.'
      };
    } else {
      overrideResult = {
        applied: true,
        code: data.overrideCode.trim().toUpperCase(),
        justification: data.overrideJustification.trim(),
        approvedBy: data.overrideCode.trim().toUpperCase(),
        appliedAt: now
      };
      auditLog.push({
        event: 'BILLING_OVERRIDE_APPLIED',
        timestamp: now,
        agent: 'billing',
        overrideCode: overrideResult.code,
        justification: overrideResult.justification,
        approvedBy: overrideResult.approvedBy
      });
    }
  }

  // --- DETERMINE STATUS ---
  let status = 'submitted';
  let message = '';

  if (data.insuranceExpired && !overrideResult?.applied) {
    status = 'rejected';
    message = `Claim rejected: ${data.insuranceErrors.join(' ')} Patient has been notified. Billing team alerted.`;
  } else if (mismatchDetected && !overrideResult?.applied) {
    status = 'held_for_review';
    message = `Claim held for review: Treatment codes ${mismatchedCodes.join(', ')} are not covered under policy ${data.insurancePolicyId}. Mismatch flagged, pending billing team review.`;
  } else if (data.slaBreached) {
    status = 'overdue';
    message = `Claim overdue: ${data.daysOutstanding} days outstanding. Auto-escalated to billing manager. SLA breach logged.`;
  } else {
    status = 'submitted';
    message = `Invoice ${invoiceId} created successfully. Amount: MYR ${data.amount}. Treatment codes: ${data.treatmentCodes.join(', ')}. Claim submitted for processing.`;
  }

  if (!data.documentationComplete && data.missingDocuments.length > 0) {
    message += ` Note: Missing documentation detected for treatment codes: ${data.missingDocuments.map(d => d.description).join(', ')}. Please submit supporting documents.`;
  }

  if (overrideResult?.applied) {
    message += ` Manual override (${overrideResult.code}) applied with justification: "${overrideResult.justification}".`;
  }

  results.push({
    json: {
      status: status,
      message: message,
      invoiceId: invoiceId,
      patientId: data.patientId,
      visitId: data.visitId,
      amount: { total: data.amount, currency: 'MYR' },
      treatmentCodes: data.treatmentCodes,
      insurancePolicyId: data.insurancePolicyId,
      idempotencyKey: data.idempotencyKey,
      insuranceExpired: data.insuranceExpired,
      documentationCheck: {
        complete: data.documentationComplete,
        missingDocuments: data.missingDocuments
      },
      coverageMismatch: {
        detected: mismatchDetected,
        mismatchedCodes: mismatchedCodes,
        coveredCodes: data.coveredCodes
      },
      slaTracking: {
        invoiceDate: data.invoiceDate,
        daysOutstanding: data.daysOutstanding,
        slaBreached: data.slaBreached
      },
      billingEscalation: data.billingEscalation,
      manualOverride: overrideResult,
      faqResponse: data.faqResponse,
      auditLog: auditLog
    }
  });
}

return results;

// ============================================================
// 🟣 RETENTION AGENT — Step 1: Validate & Parse Input
// ============================================================
// Handles: Webhook/form data unwrap, batch vs single patient
// detection, field normalization and parsing.
// ============================================================

let data = $input.first().json;
// --- UNWRAP WEBHOOK DATA ---
if (data.body && data.webhookUrl) { data = data.body; }

const now = new Date();
const nowISO = now.toISOString();

// Determine if batch or single patient
let patients = [];
if (Array.isArray(data.patients)) {
  patients = data.patients;
} else {
  patients = [{
    patientId: data.patientId || data['Patient ID'] || '',
    name: data.name || data['Patient Name'] || data.patientName || '',
    lastVisitDate: data.lastVisitDate || data['Last Visit Date'] || '',
    condition: data.condition || data['Condition/Diagnosis'] || '',
    messagingConsent: data.messagingConsent ?? data['Messaging Consent'] ?? true,
    unresolvedClinicalIssue: data.unresolvedClinicalIssue ?? data['Unresolved Clinical Issue'] ?? false,
    unresolvedBillingIssue: data.unresolvedBillingIssue ?? data['Unresolved Billing Issue'] ?? false,
    contactFrequencyCount: data.contactFrequencyCount ?? data['Contacts This Month'] ?? 0
  }];
}

return [{
  json: {
    patients: patients,
    totalPatients: patients.length,
    _timestamp: nowISO,
    _nowMs: now.getTime()
  }
}];

// ============================================================
// 🟣 RETENTION AGENT — Step 2: Inactivity Scan & Segmentation
// ============================================================
// Handles: Months inactive calculation, auto-segmentation
// (chronic/wellness/post_procedure/lapsed/at-risk),
// suppression checks, consent & frequency cap verification.
// ============================================================

const data = $input.first().json;
const now = new Date(data._nowMs);
const nowISO = data._timestamp;

// --- AUTO-SEGMENTATION FUNCTION ---
function classifySegment(patient, monthsInactive) {
  const condition = (patient.condition || '').toLowerCase();

  const chronicKeywords = ['diabetes', 'hypertension', 'heart', 'cardiac', 'kidney', 'copd', 'cancer', 'chronic', 'asthma', 'epilepsy', 'arthritis'];
  const postProcKeywords = ['surgery', 'post-op', 'procedure', 'recovery', 'transplant', 'operation'];
  const wellnessKeywords = ['wellness', 'preventive', 'checkup', 'screening', 'annual', 'routine', 'check-up'];

  let baseSegment = 'unclassified';
  let reason = 'No matching condition keywords found';

  if (chronicKeywords.some(kw => condition.includes(kw))) {
    baseSegment = 'chronic';
    reason = `Chronic condition keyword detected: "${condition}"`;
  } else if (postProcKeywords.some(kw => condition.includes(kw))) {
    baseSegment = 'post_procedure';
    reason = `Post-procedure keyword detected: "${condition}"`;
  } else if (wellnessKeywords.some(kw => condition.includes(kw))) {
    baseSegment = 'wellness';
    reason = `Wellness keyword detected: "${condition}"`;
  }

  let finalSegment = baseSegment;
  if (monthsInactive >= 12 && baseSegment !== 'chronic') {
    finalSegment = 'lapsed';
    reason += ` | Override: ${monthsInactive} months inactive (non-chronic) \u2192 lapsed`;
  } else if (monthsInactive >= 6 && baseSegment === 'chronic') {
    finalSegment = 'at-risk';
    reason += ` | Override: ${monthsInactive} months inactive (chronic) \u2192 at-risk`;
  }

  return { segment: finalSegment, reason: reason, autoClassified: true };
}

// --- PROCESS EACH PATIENT ---
const processedPatients = [];
let hasEligiblePatients = false;

for (const patient of data.patients) {
  const patientId = patient.patientId || '';
  const name = patient.name || patient.fullName || 'Patient';

  // Parse booleans from form dropdowns
  const messagingConsent = patient.messagingConsent === true || patient.messagingConsent === 'true';
  const unresolvedClinical = patient.unresolvedClinicalIssue === true || patient.unresolvedClinicalIssue === 'true';
  const unresolvedBilling = patient.unresolvedBillingIssue === true || patient.unresolvedBillingIssue === 'true';
  let contactCount = parseInt(patient.contactFrequencyCount, 10) || 0;

  // Calculate months inactive
  let monthsInactive = 0;
  let isInactive = false;
  if (patient.lastVisitDate) {
    const lastVisit = new Date(patient.lastVisitDate);
    monthsInactive = Math.floor((now - lastVisit) / (1000 * 60 * 60 * 24 * 30.44));
    isInactive = monthsInactive >= 6;
  }

  // Auto-segment
  const segmentation = classifySegment(patient, monthsInactive);

  // --- SUPPRESSION CHECKS ---
  let suppressed = false;
  let suppressionReason = '';

  if (unresolvedClinical) {
    suppressed = true;
    suppressionReason = 'Patient has unresolved clinical issue. Outreach suppressed until resolved.';
  }

  if (unresolvedBilling && !suppressed) {
    suppressed = true;
    suppressionReason = 'Patient has unresolved billing issue. Marketing outreach suppressed.';
  }

  if (!messagingConsent && !suppressed) {
    suppressed = true;
    suppressionReason = 'Patient has not provided messaging consent. No outreach permitted.';
  }

  if (contactCount >= 2 && !suppressed) {
    suppressed = true;
    suppressionReason = `Frequency cap exceeded: ${contactCount} contacts this month (max 2). Next outreach scheduled for next cycle.`;
  }

  if (!isInactive && !suppressed) {
    suppressed = true;
    suppressionReason = `Patient is not inactive (last visit ${monthsInactive} months ago, threshold: 6 months).`;
  }

  if (!suppressed) hasEligiblePatients = true;

  processedPatients.push({
    patientId, name, monthsInactive, isInactive,
    segmentClassification: segmentation,
    messagingConsent,
    suppressionFlags: {
      unresolvedClinicalIssue: unresolvedClinical,
      unresolvedBillingIssue: unresolvedBilling,
      contactFrequencyCount: contactCount,
      frequencyCapExceeded: contactCount >= 2
    },
    suppressed, suppressionReason,
    condition: patient.condition || ''
  });
}

return [{
  json: {
    patients: processedPatients,
    totalPatients: processedPatients.length,
    hasEligiblePatients: hasEligiblePatients,
    _timestamp: nowISO
  }
}];

// ============================================================
// 🟣 RETENTION AGENT — Generate Outreach Messages
// ============================================================
// Handles: Segment-specific messaging templates, outreach
// channel assignment, audit logging for eligible patients.
// ============================================================

const data = $input.first().json;
const nowISO = data._timestamp;

const segmentMessages = {
  'chronic': 'Dear {name}, it\'s been a while since your last visit. As a patient managing a chronic condition, regular check-ups are important for your health. Please book your next appointment at your earliest convenience.',
  'at-risk': 'Dear {name}, we notice you haven\'t visited in over 6 months. Managing chronic conditions requires regular monitoring. Please contact us to schedule a follow-up \u2014 your health is our priority.',
  'wellness': 'Dear {name}, it\'s time for your routine wellness check-up! Regular preventive care helps catch issues early. Book your next appointment today.',
  'post_procedure': 'Dear {name}, as a post-procedure patient, follow-up visits are essential for your recovery. Please book your next check-up to ensure everything is healing well.',
  'lapsed': 'Dear {name}, we miss you at our clinic! It\'s been over a year since your last visit. We\'d love to help you stay on top of your health. Book an appointment today.',
  'unclassified': 'Dear {name}, it\'s been a while since we last saw you. We\'re here for all your healthcare needs. Book your next appointment at your convenience.'
};

const results = [];
const auditLog = [];

for (const patient of data.patients) {
  let outreach = null;
  let action = 'suppressed';

  if (!patient.suppressed) {
    const messageTemplate = segmentMessages[patient.segmentClassification.segment] || segmentMessages['unclassified'];
    const message = messageTemplate.replace('{name}', patient.name);

    outreach = {
      channel: 'sms',
      message: message,
      segment: patient.segmentClassification.segment,
      sentAt: nowISO
    };
    action = 'outreach_sent';

    auditLog.push({
      event: 'RETENTION_OUTREACH_SENT',
      timestamp: nowISO,
      agent: 'retention',
      patientId: patient.patientId,
      segment: patient.segmentClassification.segment,
      channel: 'sms'
    });
  } else {
    auditLog.push({
      event: 'RETENTION_SUPPRESSED',
      timestamp: nowISO,
      agent: 'retention',
      patientId: patient.patientId,
      reason: patient.suppressionReason
    });
  }

  results.push({
    patientId: patient.patientId,
    name: patient.name,
    monthsInactive: patient.monthsInactive,
    isInactive: patient.isInactive,
    segmentClassification: patient.segmentClassification,
    messagingConsent: patient.messagingConsent,
    suppressionFlags: patient.suppressionFlags,
    action: action,
    suppressed: patient.suppressed,
    suppressionReason: patient.suppressed ? patient.suppressionReason : null,
    outreach: outreach
  });
}

return [{
  json: {
    status: 'processed',
    totalPatients: results.length,
    outreachSent: results.filter(r => r.action === 'outreach_sent').length,
    suppressed: results.filter(r => r.suppressed).length,
    patients: results,
    auditLog: auditLog
  }
}];

// ============================================================
// 🟣 RETENTION AGENT — All Patients Suppressed
// ============================================================
// Returns response when no patients are eligible for outreach.
// All patients are either active, on suppression list,
// lacking consent, or frequency-capped.
// ============================================================

const data = $input.first().json;
const nowISO = data._timestamp;

const results = [];
const auditLog = [];

for (const patient of data.patients) {
  auditLog.push({
    event: 'RETENTION_SUPPRESSED',
    timestamp: nowISO,
    agent: 'retention',
    patientId: patient.patientId,
    reason: patient.suppressionReason
  });

  results.push({
    patientId: patient.patientId,
    name: patient.name,
    monthsInactive: patient.monthsInactive,
    isInactive: patient.isInactive,
    segmentClassification: patient.segmentClassification,
    messagingConsent: patient.messagingConsent,
    suppressionFlags: patient.suppressionFlags,
    action: 'suppressed',
    suppressed: true,
    suppressionReason: patient.suppressionReason,
    outreach: null
  });
}

return [{
  json: {
    status: 'processed',
    totalPatients: results.length,
    outreachSent: 0,
    suppressed: results.length,
    patients: results,
    auditLog: auditLog
  }
}];
